-- (a) TIMED OUT: generated by genk-style template: one scan 2026-11-11 00:00 to 2026-11-18 07:00, key base from sessions before
--     18 Nov (p99 per dict x group on clean signature-windows, >= 500 to use), replay after. Not re-run.
-- (b) Run: replay window only, global cells.
WITH g(d,grp,gb,ms,ml) AS (SELECT * FROM VALUES (-1,'Desktop',68.7,1,1),(-1,'Mobile',68.7,1,1),(-1,'Linux',68.7,1,1),(-1,'WinRDVM',68.7,1,1),(-1,'Other',68.7,1,1),(1,'Desktop',35.3,1,1),(1,'Mobile',15.9,1,1),(1,'Linux',35.3,1,1),(1,'WinRDVM',35.3,1,1),(1,'Other',35.3,1,1),(3,'Desktop',104,1,1),(3,'Mobile',21,1,1),(3,'Linux',16.6,1,1),(3,'WinRDVM',16.4,1,1),(3,'Other',68,1,1),(7,'Desktop',29,1.5,2),(7,'Mobile',7,1.5,2),(7,'Linux',30.8,1.5,2),(7,'WinRDVM',10,1.5,2),(7,'Other',25,1.5,2),(15,'Desktop',13,2,4),(15,'Mobile',21,2,4),(15,'Linux',10.1,2,4),(15,'WinRDVM',7,1.5,2),(15,'Other',17,2,4),(31,'Desktop',27,2,4),(31,'Mobile',18,2,4),(31,'Linux',66.5,2,4),(31,'WinRDVM',7,1.5,2),(31,'Other',26,2,4),(63,'Desktop',20,2,6),(63,'Mobile',72,2,6),(63,'Linux',13,2,6),(63,'WinRDVM',20,1.5,2),(63,'Other',16.7,2,6)),
s0 AS (SELECT session_ts ts, di_dictionary_num_matched_at_session_created d, os_at_session_created os,
  COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua,
  COALESCE(user_ip_at_session_created,'') ip, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver,
  di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, COALESCE(di_short_term_threshold_ratio_at_session_created,0) str,
  IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb
  FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY
  WHERE public_key='BBCC314C-4937-4CCD-B0A3-FDF0F0F7603C' AND session_last_timestamp>='2026-11-18 00:00' AND session_last_timestamp<'2026-11-18 13:00'
    AND session_ts>='2026-11-18 00:00' AND session_ts<'2026-11-18 07:00' AND di_dictionary_num_matched_at_session_created IS NOT NULL),
s1 AS (SELECT s0.*, /* x, grp as _session_cte.sql, PROXY = FALSE */
  CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A'
       WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B'
       WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C'
       WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C'
       WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x,
  CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop'
       WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp,
  IFF(ip LIKE '2a03:4000:6:cc79:%','attack','rest') c FROM s0),
f AS (SELECT s1.*, g.gb, g.ms, g.ml, IFF(x IS NULL AND (stc>g.gb*g.ms OR ltc>g.gb*g.ml*60),1,0) nag, IFF(x IS NULL AND stc>g.gb*g.ms,1,0) nags
  FROM s1 LEFT JOIN g ON g.d=s1.d AND g.grp=s1.grp)
SELECT c||'|'||d||'|'||IFF(x IS NULL,grp,'SKIP_'||x)||'|n='||COUNT(*)||'|hi='||ROUND(100*AVG(hi),1)||'|ver='||ROUND(100*AVG(ver),1)
 ||'|gST='||COALESCE(MAX(gb*ms)::STRING,'-')||'|gLT='||COALESCE(MAX(gb*ml*60)::STRING,'-')
 ||'|stc_p10/p50/p90/max='||PERCENTILE_DISC(0.1) WITHIN GROUP (ORDER BY stc)||'/'||MEDIAN(stc)||'/'||PERCENTILE_DISC(0.9) WITHIN GROUP (ORDER BY stc)||'/'||MAX(stc)
 ||'|ltc_p50/max='||MEDIAN(ltc)||'/'||MAX(ltc)||'|thrST_today='||COALESCE(ROUND(MEDIAN(stc/NULLIF(str,0)),1)::STRING,'-')
 ||'|T='||SUM(stb)||'|T2='||SUM(IFF(str>=2,1,0))||'|T4='||SUM(IFF(str>=4,1,0))||'|TL='||SUM(ltb)||'|NAglobal='||SUM(nag)||'|NSTglobal='||SUM(nags) r
FROM f GROUP BY c,d,x,grp HAVING COUNT(*)>=20 ORDER BY 1;
